<script>import{t}from'../logic/i18n.js';import{signOut}from'../logic/auth.js';import{getMyProfile}from'../logic/db.js';let{lang='fa',user,role}=$props();let myProfile=$state(null);let loading=$state(true);let logoutConfirm=$state(false);$effect(()=>{loadData()});async function loadData(){loading=true;try{myProfile=await getMyProfile()}catch(e){}loading=false}async function handleLogout(){await signOut();window.location.hash='#/home';window.location.reload()}</script><div class="sp"><div class="sc"><div class="sh2"><h1 class="st2">{t(lang,'settings')}</h1><p class="su2">{lang==='en'?'Manage your admin account':'مدیریت حساب ادمین'}</p></div>{#if loading}<div class="se2"><span class="spi"></span><span>{t(lang,'loading')}</span></div>{:else if myProfile}<div class="pc"><div class="pa"><div class="ai">{(myProfile.display_name||user?.displayName||'A')[0]}</div><div class="an2"><span class="an3">{myProfile.display_name||user?.displayName||'-'}</span><span class="ar2">{lang==='en'?'Administrator':'مدیر سیستم'}</span></div></div><div class="pi"><div class="pir"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg><div class="pid"><span class="pil">{t(lang,'username')}</span><span class="piv" dir="ltr">{myProfile.username||user?.username}</span></div></div><div class="pir"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg><div class="pid"><span class="pil">{t(lang,'displayName')}</span><span class="piv">{myProfile.display_name||user?.displayName||'-'}</span></div></div><div class="pir"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg><div class="pid"><span class="pil">{t(lang,'role')}</span><span class="pib2">{lang==='en'?'Admin':'مدیر'}</span></div></div></div></div>{:else}<div class="se2"><p>{t(lang,'profileNotFound')}</p></div>{/if}<div class="ls">{#if !logoutConfirm}<button class="lb" onclick={()=>logoutConfirm=true}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>{t(lang,'logout')}</button>{:else}<div class="lc"><span class="lct">{lang==='en'?'Are you sure you want to log out?':'آیا مطمئن هستید که می‌خواهید خارج شوید؟'}</span><div class="lcb"><button class="lcy" onclick={handleLogout}>{lang==='en'?'Yes, log out':'بله، خارج شو'}</button><button class="lcn" onclick={()=>logoutConfirm=false}>{lang==='en'?'Cancel':'انصراف'}</button></div></div>{/if}</div><p class="sf"><a href="#/{lang}/home">← {t(lang,'backToHome')}</a></p></div></div><style>.sp{display:flex;justify-content:center;align-items:flex-start;padding:clamp(1.5rem,4vw,3rem) clamp(1rem,3vw,2rem);min-height:100%}.sc{width:clamp(360px,42vw,560px);animation:fi 300ms ease}@keyframes fi{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}.sh2{margin-bottom:clamp(1.2rem,3vw,1.8rem);text-align:center}.st2{font-size:clamp(1.2rem,3.5vw,1.5rem);color:var(--color-accent);margin:0 0 0.3rem}.su2{font-size:var(--font-size-sm);color:var(--color-text-muted);margin:0}.se2{display:flex;align-items:center;justify-content:center;gap:0.6rem;padding:2.5rem 1rem;color:var(--color-text-muted);font-size:var(--font-size-sm)}.spi{width:18px;height:18px;border:2px solid var(--color-border);border-top-color:var(--color-accent);border-radius:50%;animation:spin 0.6s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.pc{background:var(--color-bg-primary);border:1px solid var(--color-border);border-radius:var(--radius-lg);overflow:hidden;box-shadow:var(--shadow-sm);margin-bottom:clamp(1rem,3vw,1.5rem)}.pa{display:flex;align-items:center;gap:1rem;padding:clamp(1.2rem,3vw,1.6rem);background:linear-gradient(135deg,var(--color-accent-bg),var(--color-bg-primary));border-bottom:1px solid var(--color-border)}.ai{width:56px;height:56px;border-radius:50%;background:var(--color-accent);color:var(--color-accent-text);display:flex;align-items:center;justify-content:center;font-size:1.5rem;font-weight:700;flex-shrink:0}.an2{display:flex;flex-direction:column;gap:0.2rem}.an3{font-weight:700;font-size:var(--font-size-lg);color:var(--color-text-primary)}.ar2{font-size:var(--font-size-xs);color:var(--color-accent);background:var(--color-accent-bg);padding:2px 10px;border-radius:999px;width:fit-content}.pi{padding:0.35rem 0}.pir{display:flex;align-items:center;gap:0.75rem;padding:0.75rem clamp(1rem,3vw,1.6rem);transition:background var(--transition-fast)}.pir:hover{background:var(--color-bg-hover)}.pir svg{color:var(--color-text-muted);flex-shrink:0}.pid{flex:1;min-width:0}.pil{display:block;font-size:0.7rem;color:var(--color-text-muted);text-transform:uppercase;letter-spacing:0.04em;margin-bottom:0.15rem}.piv{font-size:var(--font-size-sm);color:var(--color-text-primary);font-weight:500;word-break:break-all}.pib2{display:inline-block;font-size:var(--font-size-xs);font-weight:600;padding:2px 10px;border-radius:999px;background:#064e3b;color:#34d399}:global([data-theme="dark"]) .pib2{background:#064e3b;color:#6ee7b7}.ls{padding:0.75rem 0}.lb{display:flex;align-items:center;justify-content:center;gap:0.5rem;width:100%;padding:clamp(0.55rem,1.5vw,0.7rem);border:1px solid var(--color-danger);border-radius:var(--radius-md);background:none;color:var(--color-danger);font-family:var(--font-body);font-size:var(--font-size-base);font-weight:600;cursor:pointer;transition:all var(--transition-fast)}.lb:hover{background:var(--color-danger);color:#fff}.lc{display:flex;flex-direction:column;align-items:center;gap:0.75rem;padding:1rem;background:#fef2f2;border:1px solid #fecaca;border-radius:var(--radius-md)}:global([data-theme="dark"]) .lc{background:#450a0a;border-color:#7f1d1d}.lct{font-size:var(--font-size-sm);color:#dc2626;text-align:center}:global([data-theme="dark"]) .lct{color:#fca5a5}.lcb{display:flex;gap:0.75rem;width:100%}.lcy{flex:1;padding:0.55rem;border:none;border-radius:var(--radius-md);background:#dc2626;color:#fff;font-family:var(--font-body);font-size:var(--font-size-sm);font-weight:600;cursor:pointer;transition:all var(--transition-fast)}.lcy:hover{background:#b91c1c}.lcn{flex:1;padding:0.55rem;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-bg-primary);color:var(--color-text-secondary);font-family:var(--font-body);font-size:var(--font-size-sm);font-weight:500;cursor:pointer;transition:all var(--transition-fast)}.lcn:hover{background:var(--color-bg-hover)}.sf{text-align:center;font-size:var(--font-size-sm)}.sf a{color:var(--color-link)}</style>